static void ui_rgb_light_refresh(void)
{
    uint32_t color = led_get_selected_color();
    uint8_t brightness = led_get_brightness_percent();
    int light_on = led_is_enabled();

    if (rgb_light_state_label != NULL)
    {
        if (color == 0x00FFFFFFU)
            lv_label_set_text_fmt(rgb_light_state_label, "%s - WHITE SELECTED",
                                  light_on ? "ON" : "OFF");
        else
            lv_label_set_text_fmt(rgb_light_state_label, "%s - HUE %u DEG SELECTED",
                                  light_on ? "ON" : "OFF",
                                  (unsigned int)led_get_hue_degrees());
    }

    if (rgb_light_color_preview != NULL)
    {
        lv_obj_set_style_bg_color(rgb_light_color_preview, lv_color_hex(color),
                                  LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_shadow_color(rgb_light_color_preview, lv_color_hex(color),
                                      LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_bg_opa(rgb_light_color_preview,
                                light_on ? LV_OPA_COVER : LV_OPA_30,
                                LV_PART_MAIN | LV_STATE_DEFAULT);
        lv_obj_set_style_shadow_opa(rgb_light_color_preview,
                                    light_on ? LV_OPA_70 : LV_OPA_TRANSP,
                                    LV_PART_MAIN | LV_STATE_DEFAULT);
    }

    if (rgb_light_hue_label != NULL)
    {
        if (color == 0x00FFFFFFU)
            lv_label_set_text(rgb_light_hue_label, "WHITE SELECTED");
        else
            lv_label_set_text_fmt(rgb_light_hue_label, "HUE %u DEG",
                                  (unsigned int)led_get_hue_degrees());
    }

    if (rgb_light_brightness_value_label != NULL)
        lv_label_set_text_fmt(rgb_light_brightness_value_label, "%u%%",
                              (unsigned int)brightness);
    if (rgb_light_brightness_slider != NULL &&
        lv_slider_get_value(rgb_light_brightness_slider) != brightness)
        lv_slider_set_value(rgb_light_brightness_slider, brightness, LV_ANIM_OFF);

    if (rgb_light_switch != NULL)
    {
        if (light_on)
            lv_obj_add_state(rgb_light_switch, LV_STATE_CHECKED);
        else
            lv_obj_clear_state(rgb_light_switch, LV_STATE_CHECKED);
    }

    if (rgb_light_auto_off_detail_label != NULL)
        lv_label_set_text(rgb_light_auto_off_detail_label,
                          led_get_auto_off_description());
    if (rgb_light_auto_off_badge_label != NULL)
        lv_label_set_text(rgb_light_auto_off_badge_label,
                          led_get_auto_off_label());
    if (rgb_light_effect_detail_label != NULL)
        lv_label_set_text(rgb_light_effect_detail_label,
                          led_get_effect_description());
    if (rgb_light_effect_badge_label != NULL)
        lv_label_set_text(rgb_light_effect_badge_label,
                          led_get_effect_label());
}

void ui_RgbLight_refresh_state(void)
{
    if (ui_RgbLight != NULL)
        ui_rgb_light_refresh();
}

static void rgb_light_back_event(lv_event_t *e)
{
    if (lv_event_get_code(e) == LV_EVENT_CLICKED)
        ui_RgbLight_return();
}

static void rgb_light_switch_event(lv_event_t *e)
{
    int requested_state;

    if (lv_event_get_code(e) != LV_EVENT_VALUE_CHANGED)
        return;

    requested_state = lv_obj_has_state(lv_event_get_target(e), LV_STATE_CHECKED) ? 1 : 0;
    if (requested_state != led_is_enabled())
        on_led_toggle(e);
    ui_rgb_light_refresh();
}

static void rgb_light_colorwheel_event(lv_event_t *e)
{
    if (lv_event_get_code(e) == LV_EVENT_VALUE_CHANGED)
    {
        on_colorwheel_changed(e);
        ui_rgb_light_refresh();
    }
}

static void rgb_light_white_color_event(lv_event_t *e)
{
    if (lv_event_get_code(e) == LV_EVENT_CLICKED)
    {
        on_white_color_selected(e);
        ui_rgb_light_refresh();
    }
}

static void rgb_light_brightness_event(lv_event_t *e)
{
    if (lv_event_get_code(e) == LV_EVENT_VALUE_CHANGED)
    {
        on_rgb_brightness_changed(e);
        ui_rgb_light_refresh();
    }
}

static void rgb_light_auto_off_event(lv_event_t *e)
{
    if (lv_event_get_code(e) == LV_EVENT_CLICKED)
    {
        led_cycle_auto_off_delay();
        ui_rgb_light_refresh();
    }
}

static void rgb_light_effect_event(lv_event_t *e)
{
    if (lv_event_get_code(e) == LV_EVENT_CLICKED)
    {
        led_cycle_effect();
        ui_rgb_light_refresh();
    }
}

// event functions
void ui_event_RgbLight(lv_event_t *e)
{
    lv_indev_t *indev;

    if (lv_event_get_code(e) != LV_EVENT_GESTURE)
        return;

    indev = lv_indev_get_act();
    if (indev != NULL && lv_indev_get_gesture_dir(indev) == LV_DIR_RIGHT)
        ui_RgbLight_return();
}

