void ui_RgbLight_screen_destroy(void)
{
    if (ui_RgbLight != NULL)
        lv_obj_del(ui_RgbLight);

    ui_RgbLight = NULL;
    ui_RgbLightContent = NULL;
    ui_RgbLightColorwheel = NULL;
    rgb_light_state_label = NULL;
    rgb_light_color_preview = NULL;
    rgb_light_hue_label = NULL;
    rgb_light_brightness_value_label = NULL;
    rgb_light_brightness_slider = NULL;
    rgb_light_switch = NULL;
    rgb_light_auto_off_detail_label = NULL;
    rgb_light_auto_off_badge_label = NULL;
    rgb_light_effect_detail_label = NULL;
    rgb_light_effect_badge_label = NULL;
}
